import { Context, Layer } from "effect"

export interface WorkerBindings {
  readonly ACCESS_AUDIENCE: string
  readonly ACCESS_TEAM_DOMAIN: string
  readonly ADMIN_ALLOWED_ORIGINS: string
  readonly ANDROID_MINIMUM_VERSION: string
  readonly ANDROID_STORE_URL: string
  readonly API_BOT_TOKEN: string
  readonly API_CACHE: KVNamespace
  readonly APP_UPDATES: R2Bucket
  readonly APP_UPDATES_PUBLIC_ORIGIN: string
  readonly CLASH_PROXY: Fetcher
  readonly ENVIRONMENT: string
  readonly FORCED_UPDATE_MESSAGE: string
  readonly HYPERDRIVE: Hyperdrive
  readonly IOS_MINIMUM_VERSION: string
  readonly IOS_STORE_URL: string
  readonly POSTS: R2Bucket
  readonly POSTS_PUBLIC_ORIGIN: string
  readonly TENOR_ALLOWED_HOSTS: string
  readonly TRACKING: Fetcher
}

export class WorkerEnvironment extends Context.Service<
  WorkerEnvironment,
  WorkerBindings
>()("clashking/WorkerEnvironment") {
  static layer(bindings: WorkerBindings) {
    return Layer.succeed(WorkerEnvironment, bindings)
  }
}
