import { Effect, Layer } from "effect"

import { AccessIdentity } from "./access.js"
import { databaseLayer, refreshMaterializedViews } from "./database.js"
import { WorkerEnvironment, type WorkerBindings } from "./environment.js"
import { recoverDefect, recoverRoute, route } from "./router.js"
import { TenorResolver } from "./tenor.js"

const liveLayer = (bindings: WorkerBindings) => {
  const environment = WorkerEnvironment.layer(bindings)
  const services = Layer.mergeAll(AccessIdentity.layer, TenorResolver.layer).pipe(
    Layer.provideMerge(environment),
  )
  return Layer.mergeAll(services, databaseLayer(bindings))
}

export default {
  fetch(request: Request, bindings: WorkerBindings, context: ExecutionContext): Promise<Response> {
    const requestId = request.headers.get("x-request-id") ?? crypto.randomUUID()
    const startedAt = Date.now()
    const program = route(request, bindings).pipe(
      recoverRoute(requestId),
      recoverDefect,
      Effect.tap((response) =>
        Effect.sync(() => {
          console.log(JSON.stringify({
            event: "request_complete",
            method: request.method,
            path: new URL(request.url).pathname,
            request_id: requestId,
            status: response.status,
            duration_ms: Date.now() - startedAt,
          }))
        }),
      ),
      Effect.provide(liveLayer(bindings)),
      Effect.scoped,
    )
    const response = Effect.runPromise(program)
    context.waitUntil(response.then(() => undefined))
    return response.then((value) => {
      const headers = new Headers(value.headers)
      headers.set("x-request-id", requestId)
      return new Response(value.body, { status: value.status, statusText: value.statusText, headers })
    })
  },

  scheduled(_controller: ScheduledController, bindings: WorkerBindings, context: ExecutionContext): void {
    const program = refreshMaterializedViews.pipe(
      Effect.tap((result) => Effect.logInfo("materialized_view_refresh_complete", { result })),
      Effect.catch((failure) =>
        Effect.logError("materialized_view_refresh_failed", { failure }).pipe(
          Effect.flatMap(() => Effect.fail(failure)),
        ),
      ),
      Effect.provide(databaseLayer(bindings)),
      Effect.scoped,
    )
    context.waitUntil(Effect.runPromise(program))
  },
} satisfies ExportedHandler<WorkerBindings>
